export interface BlurPassOptions {
    /** Blur radius in texels (Default: 4. 0 = bypass) */
    radius?: number;

    /** Number of blur iterations for deeper defocus (Default: 1) */
    iterations?: number;

    /** Custom pass label */
    name?: string;
}

import { PostProcessPass, createTextureHandle } from "retiam";

const chromaticAberrationPass = new PostProcessPass(
    "ChromaticAberration",
    sceneColorHandle,
    `
    @fragment fn fs_main(@builtin(position) pos: vec4f) -> @location(0) vec4f {
        let uv = pos.xy / view.size;
        let dist = length(uv - 0.5);
        let offset = vec2f(dist * 0.008, 0.0);

        let r = textureSample(inputTexture, texSampler, uv + offset).r;
        let g = textureSample(inputTexture, texSampler, uv).g;
        let b = textureSample(inputTexture, texSampler, uv - offset).b;

        return vec4f(r, g, b, 1.0);
    }
    `
);

import { Scene, Shader } from "retiam";

const scene = new Scene({ canvas });

// Animated plasma ripple surface
const plasma = new Shader(8.0, 5.0, `
    let uv = input.uv * 4.0;
    let v1 = sin(uv.x + view.time);
    let v2 = sin(uv.y + view.time * 1.5);
    let v3 = sin(uv.x + uv.y + view.time);
    let col = 0.5 + 0.5 * vec3f(v1, v2, v3);
    finalColor = vec4f(col, 1.0);
`);
scene.add(plasma);
